  slug: 'best-ramen-in-new-york-city',
  title: '50 Best Ramen Restaurants In New York City',
  h1: '50 Best Ramen Restaurants In New York City',
  description: 'Looking for the best ramen in New York City? We ranked the top 50 ramen restaurants in NYC by rating, reviews, and broth quality — from Midtown to the Lower East Side, covering every style from tonkotsu to tsukemen.',
